  ('s1', 1, '{"ru": "Тимур: первые слова", "kk": "Тимур: алғашқы сөздер"}'::jsonb, 'Тимур', '3-5', '{"ru": "В 3,5 года почти не говорил, объяснялся жестами и часто злился.", "kk": "3,5 жасында сөйлемейтін, ыммен түсіндіріп, жиі ашуланатын."}'::jsonb, '[{"ru": "логопед", "kk": "логопед"}, {"ru": "нейропсихолог", "kk": "нейропсихолог"}]'::jsonb, '2026-08-17', '{"ru": "Мама вела дневник каждый день и раз в месяц показывала отчёт логопеду. За три месяца появились первые фразы, а истерик стало заметно меньше.", "kk": "Анасы күнделікті күнделік жүргізіп, айына бір рет есепті логопедке көрсетті. Үш айда алғашқы сөз тіркестері пайда болды, ашу-ыза азайды."}'::jsonb, '{"ru": "Занятия с логопедом 2 раза в неделю, игры с карточками дома по 10 минут, меньше мультфильмов.", "kk": "Логопедпен аптасына 2 рет сабақ, үйде карточкалармен 10 минут ойын, мультфильмді азайту."}'::jsonb, '[{"week": 2, "ru": "Первое занятие с логопедом", "kk": "Логопедпен алғашқы сабақ"}, {"week": 5, "ru": "Сказал «мама» и «дай» сам", "kk": "Өзі «мама» және «бер» деді"}, {"week": 9, "ru": "Повторяет слова из мультфильмов", "kk": "Мультфильмдегі сөздерді қайталайды"}, {"week": 12, "ru": "Первые фразы из двух слов", "kk": "Екі сөзден тұратын алғашқы сөйлемдер"}]'::jsonb, '[{"start": "2026-08-17", "good": 2, "normal": 3, "bad": 2, "new_word": 0, "tantrum": 5, "bad_sleep": 1, "bad_eat": 0, "homework": 0}, {"start": "2026-08-24", "good": 3, "normal": 2, "bad": 2, "new_word": 0, "tantrum": 5, "bad_sleep": 2, "bad_eat": 0, "homework": 0}, {"start": "2026-08-31", "good": 2, "normal": 3, "bad": 2, "new_word": 1, "tantrum": 4, "bad_sleep": 1, "bad_eat": 0, "homework": 0}, {"start": "2026-09-07", "good": 4, "normal": 2, "bad": 1, "new_word": 1, "tantrum": 4, "bad_sleep": 2, "bad_eat": 0, "homework": 0}, {"start": "2026-09-14", "good": 3, "normal": 2, "bad": 2, "new_word": 2, "tantrum": 3, "bad_sleep": 0, "bad_eat": 0, "homework": 0}, {"start": "2026-09-21", "good": 3, "normal": 2, "bad": 2, "new_word": 3, "tantrum":