  ('s2', 2, '{"ru": "Аружан: спокойный сон", "kk": "Аружан: тыныш ұйқы"}'::jsonb, 'Аружан', '1-3', '{"ru": "Просыпалась по 4–5 раз за ночь, днём была раздражительной.", "kk": "Түнде 4–5 рет оянатын, күндіз ашуланшақ болатын."}'::jsonb, '[{"ru": "детский невролог", "kk": "балалар неврологы"}, {"ru": "детский психолог", "kk": "балалар психологы"}]'::jsonb, '2026-09-07', '{"ru": "Дневник помог увидеть связь: после насыщенных дней сон был хуже. Режим и спокойные вечера дали результат примерно через месяц.", "kk": "Күнделік байланысты көруге көмектесті: күн қарбалас болса, ұйқы нашарлайды. Күн тәртібі мен тыныш кештер шамамен бір айдан кейін нәтиже берді."}'::jsonb, '{"ru": "Одинаковый ритуал перед сном, без экранов за час до сна, консультация невролога.", "kk": "Ұйықтар алдында бірдей рәсім, ұйқыға бір сағат қалғанда экрансыз, невролог кеңесі."}'::jsonb, '[{"week": 1, "ru": "Начали вести дневник сна", "kk": "Ұйқы күнделігін бастадық"}, {"week": 3, "ru": "Консультация невролога, новый режим", "kk": "Невролог кеңесі, жаңа күн тәртібі"}, {"week": 6, "ru": "Первая ночь без пробуждений", "kk": "Оянбай өткен алғашқы түн"}, {"week": 10, "ru": "Просыпается не чаще раза за ночь", "kk": "Түнде бір реттен артық оянбайды"}]'::jsonb, '[{"start": "2026-09-07", "good": 2, "normal": 3, "bad": 2, "new_word": 0, "tantrum": 2, "bad_sleep": 5, "bad_eat": 0, "homework": 0}, {"start": "2026-09-14", "good": 2, "normal": 3, "bad": 2, "new_word": 0, "tantrum": 3, "bad_sleep": 5, "bad_eat": 0, "homework": 0}, {"start": "2026-09-21", "good": 3, "normal": 2, "bad": 2, "new_word": 0, "tantrum": 3, "bad_sleep": 4, "bad_eat": 0, "homework": 0}, {"start": "2026-09-28", "good": 3, "normal": 2, "bad": 2, "new_word": 0, "tantrum": 3, "bad_sleep": 4, "bad_eat": 0, "homework": 0}, {"start": "2026-10-05", "good": 4, "normal": 2, "bad": 1, "new_word": 0, "tantrum": 2, "bad_sleep": 3, "bad_eat": 0, "homework": 0}, {"start": "2026-10-12", "good": 4, "normal": 2, "bad": 1, "new_word": 0, "tantrum": 1, "bad_slee