  ('s3', 3, '{"ru": "Дамир: внимание и уроки", "kk": "Дамир: зейін және сабақ"}'::jsonb, 'Дамир', 'over7', '{"ru": "Во 2 классе не успевал на уроках, домашнее задание растягивалось на весь вечер.", "kk": "2-сыныпта сабақта үлгермейтін, үй тапсырмасы кешке созылатын."}'::jsonb, '[{"ru": "нейропсихолог", "kk": "нейропсихолог"}, {"ru": "специальный педагог", "kk": "арнайы педагог"}]'::jsonb, '2026-07-27', '{"ru": "Нейропсихолог подобрал упражнения, а дневник показал, в какие дни уроки даются легче. Домашние задания стали делаться без слёз почти каждый день.", "kk": "Нейропсихолог жаттығулар таңдады, ал күнделік қай күндері сабақ жеңіл болатынын көрсетті. Үй тапсырмасы күн сайын дерлік көз жассыз орындалатын болды."}'::jsonb, '{"ru": "Короткие подходы по 15 минут с перерывами, нейропсихологические упражнения, договорённость с учителем.", "kk": "15 минуттық қысқа тәсілдер мен үзілістер, нейропсихологиялық жаттығулар, мұғаліммен келісім."}'::jsonb, '[{"week": 2, "ru": "Диагностика у нейропсихолога", "kk": "Нейропсихолог диагностикасы"}, {"week": 5, "ru": "Новый режим уроков с перерывами", "kk": "Үзілісі бар жаңа сабақ тәртібі"}, {"week": 10, "ru": "Первая неделя без замечаний в дневнике", "kk": "Күнделікте ескертусіз алғашқы апта"}, {"week": 14, "ru": "Домашнее задание — за час", "kk": "Үй тапсырмасы — бір сағатта"}]'::jsonb, '[{"start": "2026-07-27", "good": 2, "normal": 2, "bad": 1, "new_word": 0, "tantrum": 2, "bad_sleep": 0, "bad_eat": 0, "homework": 1}, {"start": "2026-08-03", "good": 2, "normal": 2, "bad": 3, "new_word": 0, "tantrum": 1, "bad_sleep": 0, "bad_eat": 0, "homework": 1}, {"start": "2026-08-10", "good": 3, "normal": 2, "bad": 2, "new_word": 0, "tantrum": 2, "bad_sleep": 0, "bad_eat": 0, "homework": 1}, {"start": "2026-08-17", "good": 4, "normal": 2, "bad": 1, "new_word": 0, "tantrum": 1, "bad_sleep": 0, "bad_eat": 0, "homework": 3}, {"start": "2026-08-24", "good": 4, "normal": 2, "bad": 1, "new_word": 0, "tantrum": 2, "bad_sleep": 0, "bad_eat": 0, "homewo